from pathlib import Path

# 1) Shared gesture completion policy (testable, Android-free logic).
Path('app/src/main/java/ru/zvonilka/prototype/GesturePolicy.kt').write_text('''package ru.zvonilka.prototype\n\nobject GesturePolicy {\n    fun shouldComplete(\n        offset:Float,\n        distance:Float,\n        velocity:Float,\n        positionThreshold:Float,\n        flingMinProgress:Float,\n        flingVelocity:Float\n    ):Boolean {\n        if(distance<=0f) return false\n        val progress=(offset/distance).coerceIn(0f,1f)\n        return progress>=positionThreshold || (progress>=flingMinProgress && velocity>=flingVelocity)\n    }\n}\n''')

Path('app/src/test/java/ru/zvonilka/prototype/GesturePolicyTest.kt').write_text('''package ru.zvonilka.prototype\n\nimport org.junit.Assert.*\nimport org.junit.Test\n\nclass GesturePolicyTest {\n    @Test fun positionThresholdCompletes() {\n        assertTrue(GesturePolicy.shouldComplete(72f,100f,0f,.72f,.25f,1200f))\n    }\n    @Test fun fastFlingCompletesAfterMinimumTravel() {\n        assertTrue(GesturePolicy.shouldComplete(30f,100f,1600f,.72f,.25f,1200f))\n    }\n    @Test fun tinyFlingNeverCompletes() {\n        assertFalse(GesturePolicy.shouldComplete(10f,100f,2500f,.72f,.25f,1200f))\n    }\n    @Test fun slowShortDragReturns() {\n        assertFalse(GesturePolicy.shouldComplete(50f,100f,500f,.72f,.25f,1200f))\n    }\n}\n''')

# 2) Rebuild answer slider around direct 1:1 dragging + velocity-aware, interruptible spring settling.
Path('app/src/main/java/ru/zvonilka/prototype/CallSlideAction.kt').write_text('''package ru.zvonilka.prototype\n\nimport android.os.Build\nimport android.view.HapticFeedbackConstants\nimport androidx.compose.animation.core.Animatable\nimport androidx.compose.animation.core.Spring\nimport androidx.compose.animation.core.spring\nimport androidx.compose.foundation.background\nimport androidx.compose.foundation.border\nimport androidx.compose.foundation.gestures.Orientation\nimport androidx.compose.foundation.gestures.draggable\nimport androidx.compose.foundation.gestures.rememberDraggableState\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.shape.CircleShape\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.*\nimport androidx.compose.ui.draw.clip\nimport androidx.compose.ui.graphics.Color\nimport androidx.compose.ui.graphics.vector.ImageVector\nimport androidx.compose.ui.platform.LocalDensity\nimport androidx.compose.ui.platform.LocalView\nimport androidx.compose.ui.semantics.*\nimport androidx.compose.ui.unit.*\nimport kotlinx.coroutines.Job\nimport kotlinx.coroutines.launch\nimport kotlin.math.roundToInt\n\n@Composable fun CallSlideAction(label:String,color:Color,icon:ImageVector,onComplete:()->Unit) {\n    val scope=rememberCoroutineScope()\n    val view=LocalView.current\n    val action by rememberUpdatedState(onComplete)\n    var offset by remember{mutableFloatStateOf(0f)}\n    var settleJob by remember{mutableStateOf<Job?>(null)}\n    BoxWithConstraints(Modifier.fillMaxWidth().height(72.dp).clip(CircleShape).background(Color.White.copy(alpha=.18f)).border(1.dp,Color.White.copy(alpha=.12f),CircleShape).semantics {\n        contentDescription=label+". Передвиньте ползунок вправо"\n        customActions=listOf(CustomAccessibilityAction(label){action();true})\n    }) {\n        val thumbPx=with(LocalDensity.current){64.dp.toPx()}\n        val travel=(constraints.maxWidth-thumbPx-with(LocalDensity.current){8.dp.toPx()}).coerceAtLeast(1f)\n        Text(label,Modifier.align(Alignment.Center).padding(start=44.dp),color=Color.White.copy(alpha=(1f-offset/travel).coerceIn(0f,1f)),fontSize=20.sp)\n        val dragState=rememberDraggableState { delta->offset=(offset+delta).coerceIn(0f,travel) }\n        Surface(\n            Modifier.padding(4.dp).offset{IntOffset(offset.roundToInt(),0)}.size(64.dp).draggable(\n                state=dragState,orientation=Orientation.Horizontal,\n                onDragStarted={settleJob?.cancel()},\n                onDragStopped={velocity->\n                    settleJob=scope.launch {\n                        val complete=GesturePolicy.shouldComplete(offset,travel,velocity,.72f,.25f,1200f)\n                        val target=if(complete) travel else 0f\n                        val anim=Animatable(offset)\n                        anim.animateTo(target,spring(dampingRatio=Spring.DampingRatioNoBouncy,stiffness=Spring.StiffnessMediumLow),initialVelocity=velocity) { offset=value }\n                        if(complete) {\n                            val haptic=if(Build.VERSION.SDK_INT>=30) HapticFeedbackConstants.CONFIRM else HapticFeedbackConstants.VIRTUAL_KEY\n                            view.performHapticFeedback(haptic)\n                            action()\n                        }\n                    }\n                }\n            ),shape=CircleShape,color=color\n        ) {\n            Box(contentAlignment=Alignment.Center){Icon(icon,null,Modifier.size(28.dp),tint=Color.White)}\n        }\n    }\n}\n''')

# 3) SwipeCall: 1:1 drag, velocity projection decision, interruptible spring and short confirm haptic.
p=Path('app/src/main/java/ru/zvonilka/prototype/Ui.kt')
s=p.read_text()
s=s.replace('import androidx.compose.animation.core.Animatable\n','import androidx.compose.animation.core.Animatable\nimport androidx.compose.animation.core.Spring\nimport androidx.compose.animation.core.spring\n',1)
s=s.replace('import androidx.compose.foundation.gestures.detectHorizontalDragGestures\n','import androidx.compose.foundation.gestures.Orientation\nimport androidx.compose.foundation.gestures.draggable\nimport androidx.compose.foundation.gestures.rememberDraggableState\n',1)
s=s.replace('import androidx.compose.ui.draw.clip\n','import androidx.compose.ui.draw.clip\nimport android.os.Build\nimport android.view.HapticFeedbackConstants\n',1)
s=s.replace('import kotlinx.coroutines.launch\n','import kotlinx.coroutines.Job\nimport kotlinx.coroutines.launch\n',1)
start=s.index('@OptIn(ExperimentalFoundationApi::class)\n@Composable fun SwipeCall')
end=s.index('\n@Composable fun Confirm',start)
new='''@OptIn(ExperimentalFoundationApi::class)\n@Composable fun SwipeCall(modifier:Modifier=Modifier,onCall:()->Unit,onTap:()->Unit,onLong:()->Unit={},enabled:Boolean=true,shape:androidx.compose.ui.graphics.Shape=RoundedCornerShape(20.dp),containerColor:Color=MaterialTheme.colorScheme.surface,content:@Composable ()->Unit) {\n    var offset by remember { mutableFloatStateOf(0f) }; val scope=rememberCoroutineScope(); var width by remember { mutableIntStateOf(1) }\n    var settleJob by remember { mutableStateOf<Job?>(null) }\n    val view=LocalView.current\n    val call by rememberUpdatedState(onCall)\n    val dragState=rememberDraggableState { delta->if(enabled) offset=(offset+delta).coerceIn(0f,width.toFloat()) }\n    Box(modifier.clip(shape).onSizeChanged { width=it.width }) {\n        Box(Modifier.matchParentSize().background(if(offset>0f) Ocean else containerColor)) {\n            if(offset>0f) Icon(Icons.Default.Call,null,Modifier.align(Alignment.CenterStart).padding(start=24.dp),tint=Color.White)\n        }\n        Box(Modifier.offset { IntOffset(offset.toInt(),0) }.fillMaxWidth().background(containerColor)\n            .draggable(state=dragState,orientation=Orientation.Horizontal,enabled=enabled,onDragStarted={settleJob?.cancel()},onDragStopped={velocity->\n                settleJob=scope.launch {\n                    val complete=GesturePolicy.shouldComplete(offset,width.toFloat(),velocity,.65f,.22f,1400f)\n                    val target=if(complete) width.toFloat() else 0f\n                    val anim=Animatable(offset)\n                    anim.animateTo(target,spring(dampingRatio=Spring.DampingRatioNoBouncy,stiffness=Spring.StiffnessMediumLow),initialVelocity=velocity){offset=value}\n                    if(complete) {\n                        val haptic=if(Build.VERSION.SDK_INT>=30) HapticFeedbackConstants.CONFIRM else HapticFeedbackConstants.VIRTUAL_KEY\n                        view.performHapticFeedback(haptic);offset=0f;call()\n                    }\n                }\n            })\n            .combinedClickable(enabled=enabled,onClick=onTap,onLongClick=onLong)) { content() }\n    }\n}\n'''
s=s[:start]+new+s[end:]
p.write_text(s)

